        op = re.search(rf"{var}\b.*?\n", code)
    writes = bool(re.search(r"\.(put_item|update_item|delete_item)\(", code))
    print(f"{f['name']:26s} -> {lid:32s} policies={pol.count('Policy:')}"
          f" writes={writes} env={sorted(want_env)}")

print("\nPROBLEMS:", len(problems))
for x in problems: print("  -", x)
